declaration.template:
@if (label()) {
<span class="pct-widget__label" data-pct-part="label">
  {{ label() }} @if (items().length === 0) {
  <span class="pct-widget__mark" aria-hidden="true">*</span>
  }
</span>
}

<!--
  A `value` with a word on a button that is no `<input>`: a `<button>` takes its name from
  `aria-label` or its content, never from `value`, and only an `<input>` of a button type speaks
  through it.
-->
<button
  class="pct-widget__toggle"
  data-pct-part="toggle"
  type="button"
  [value]="'next'"
  [attr.aria-label]="collapseText()"
  [attr.aria-expanded]="open()"
  (click)="toggle()"
></button>

<ul class="pct-widget__list" data-pct-part="list">
  @for (item of items(); track item) {
  <li class="pct-widget__item" data-pct-part="item">{{ item }}</li>
  } @empty {
  <li class="pct-widget__empty" data-pct-part="empty">{{ emptyText() }}</li>
  }
</ul>

<!--
  Arrays of `consts` the package read places by the instruction taking each: the attributes of a
  block whose root element listens (`@if`, `@for`, `@empty`, `@boundary`), the block's own array
  beside the element's; the local references of an element, of one with children, of a
  container, of one with children and of a template, named as speaking attributes are; a `@defer`
  block's timings. The three elements in a row are one chained call, its third link's arrays
  taken by the instruction at its root. Read as attributes, a reference here fires point 2 on a
  correct template; left unplaced, any of them fires it too.
-->
@if (open()) {
<span class="pct-widget__if" (click)="toggle()"></span>
}
<span class="pct-widget__element" #title></span>
<span class="pct-widget__second"></span>
<span class="pct-widget__third" #third></span>
@for (item of items(); track item) {
<span class="pct-widget__for" (click)="toggle()"></span>
} @empty {
<span class="pct-widget__none" (click)="toggle()"></span>
}
<span #download><span></span></span>
@boundary {
<span class="pct-widget__boundary" (click)="toggle()"></span>
} @error {
<span></span>
}
<span class="pct-widget__after"></span>
@defer (on idle; when open()) {
<span></span>
} @loading (after 100ms) {
<span></span>
} @placeholder (minimum 500ms) {
<span></span>
} @error {
<span></span>
}
<ng-container class="pct-widget__container" #alt></ng-container>
<ng-container class="pct-widget__container-start" #abbr>
  <span></span>
</ng-container>
<ng-template class="pct-widget__template" #placeholder></ng-template>

<!--
  An `attr.` binding sets the attribute under the name it gives, `setAttribute('ariaLabel', …)`
  makes `arialabel`, and no ARIA attribute is set: the word reaches no user. Only a property
  binding reaches `aria-label` through the reflection.
-->
<span class="pct-widget__attr" [attr.ariaLabel]="'Unread'"></span>

<!--
  A node of every kind the walk knows (`KNOWN_NODES`) but an ICU, which point 3 refuses, so that a
  kind taken off the list refuses this input — a `@defer` block's triggers of two classes — and
  what the compiler's visitor does not hand on and the walk passes over: a projection's `select`
  and `ngProjectAs`, and an exhaustive `@switch` block's `never`.
-->
@let count = items().length;
<ng-content select="[pctSlot]" ngProjectAs="span">{{ count }}</ng-content>
@switch (open()) { @case (true) {
<span></span>
} @case (false) {
<span></span>
} @default never; }

<!--
  Names a printed expression reads, none standing for a literal with a letter (`Names`): a mark a
  `@let` holds, which has none; a loop's index, which the block makes, beside its item, which
  stands for a collection of axis values and is read in a comparison alone; a `@let` that holds a
  comparison and is read as a condition alone; a `@let` holding a template, which is no string;
  and a template's variable, which nothing hands a string, while the nodes around it are handed
  words.
-->
@let mark = '*';
<span aria-hidden="true">{{ mark }}</span>
@let narrow = size() === 'sm'; @if (narrow) {
<span></span>
} @for (axis of ['sm', 'md']; track axis; let i = $index) {
<span [class.pct-widget__current]="axis === size()">{{ i }}</span>
} @let custom = placeholder;
<span aria-hidden="true">{{ custom ? '*' : '' }}</span>
<ng-template #row let-item><span>{{ item }}</span></ng-template>
